pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address who1, address who2, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 balWho1Before;
        try c.getBalance(who1) returns (uint256 __r) { balWho1Before = __r; } catch { return; }
        uint256 balWho2Before;
        try c.getBalance(who2) returns (uint256 __r) { balWho2Before = __r; } catch { return; }
        uint256 retWho1;
        try c.getBalance(who1) returns (uint256 __r) { retWho1 = __r; } catch { return; }
        uint256 retWho2;
        try c.getBalance(who2) returns (uint256 __r) { retWho2 = __r; } catch { return; }
        uint256 balWho1After;
        try c.getBalance(who1) returns (uint256 __r) { balWho1After = __r; } catch { return; }
        uint256 balWho2After;
        try c.getBalance(who2) returns (uint256 __r) { balWho2After = __r; } catch { return; }
        assertTrue(retWho1 == balWho1Before && retWho2 == balWho2Before && balWho1After == balWho1Before && balWho2After == balWho2Before);
    }

    function testFuzz_run(address who1, address who2, uint256 amount) public {
        vm.assume(who1.code.length == 0 && uint160(who1) > 0xffff && who1 != address(this) && who1 != address(c) && who1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && who1 != 0x000000000000000000636F6e736F6c652e6c6f67 && who1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && who1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(who2.code.length == 0 && uint160(who2) > 0xffff && who2 != address(this) && who2 != address(c) && who2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && who2 != 0x000000000000000000636F6e736F6c652e6c6f67 && who2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && who2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
